def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    k = int(data[1])

    if k >= n:
        print(0)
        return

    # Precompute factorials and inverse factorials
    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i - 1] * i % MOD
    inv_fact = [1] * (n + 1)
    inv_fact[n] = mod_pow(fact[n], MOD - 2, MOD)
    for i in range(n, 0, -1):
        inv_fact[i - 1] = inv_fact[i] * i % MOD

    def comb(a, b):
        if b < 0 or b > a:
            return 0
        return fact[a] * inv_fact[b] % MOD * inv_fact[a - b] % MOD

    ans = 0
    # Sum over m = 0..n-1: C(n-1, m) * (n-1-m)! * C(m, k)
    for m in range(k, n):
        term = comb(n - 1, m) * fact[n - 1 - m] % MOD
        term = term * comb(m, k) % MOD
        ans = (ans + term) % MOD

    print(ans)

